  Lemma ph_Ebad : forall regs m (h : Z),
    (20000 < h < 2 ^ 64)%Z -> getr regs 11 = Z_to_bv 64 h -> getr regs 13 = Z_to_bv 64 20001 ->
    rdn SEGS m (Z_to_bv 64 0x1125c8) 8 = Some (Z_to_le_bytes 8 0x1137b8) -> rdn SEGS m (Z_to_bv 64 0x1137b8) 4 = Some (Z_to_le_bytes 4 3) ->
    exists regs',
      msteps SEGS (mkst regs (0x6ca24 : word) m rom) (mkst regs' (0x63080 : word) m rom)
      /\ getr regs' 10 = Z_to_bv 64 0x18b5e /\ getr regs' 11 = Z_to_bv 64 0x15a2c /\ getr regs' 1 = Z_to_bv 64 0x6ca50
      /\ regs_agree (fun r => In r [1; 10; 11]%list) regs regs'.
Proof.
