  Lemma ph_G : forall regs m,
    rdn SEGS m (Z_to_bv 64 0x1125c8) 8 = Some (Z_to_le_bytes 8 0x1137b8) -> rdn SEGS m (Z_to_bv 64 0x1137b8) 4 = Some (Z_to_le_bytes 4 3) ->
    exists regs',
      msteps SEGS (mkst regs (0x6c974 : word) m rom) (mkst regs' (0x6c998 : word) m rom)
      /\ getr regs' 10 = Z_to_bv 64 0x12dcc /\ getr regs' 11 = Z_to_bv 64 0x15a2c
      /\ regs_agree (fun r => In r [10; 11]%list) regs regs'.
Proof.
