    exists regs',
      msteps SEGS (mkst regs (0x6ca90 : word) m rom) (mkst regs' (0x6c998 : word) m rom)
      /\ getr regs' 10 = Z_to_bv 64 0x126da /\ getr regs' 11 = Z_to_bv 64 0x15a2c
      /\ regs_agree (fun r => In r [10; 11]%list) regs regs'.
